-- Cleveland Metroparks reservation boundary import  (ROTV issue #198)
-- Source : OpenStreetMap via Overpass API (ODbL 1.0, http://osm.org/copyright)
-- Tooling: data/boundaries/fetch_cleveland_metroparks.py  (re-runnable)
-- Retrieved: 2026-05-21    Reservations: 18
--
-- Model matches the Summit Metro Parks import: poi_roles contains 'boundary',
-- boundary_type='park' (Parks panel), grounding reads PostGIS boundary_geom,
-- overlapping OSM geometry dissolved with ST_UnaryUnion (NOT ST_MakeValid).
BEGIN;

SELECT setval(pg_get_serial_sequence('pois', 'id'),
              (SELECT GREATEST(MAX(id), 1) FROM pois));

-- One POI per park (spec 048): a park that already exists keeps its row and
-- everything attached to it; only its outline is refreshed. Never delete and
-- re-insert a park: that cascades away its news, events, photos and favorites.
CREATE TEMP TABLE park_import (
  name TEXT, poi_roles TEXT[], boundary_type TEXT, boundary_color TEXT, geometry JSONB
) ON COMMIT DROP;

INSERT INTO park_import (name, poi_roles, boundary_type, boundary_color, geometry)
