UPDATE pois p
SET geometry = i.geometry, boundary_color = i.boundary_color, updated_at = CURRENT_TIMESTAMP
FROM park_import i
WHERE p.name = i.name
  AND 'boundary' = ANY(p.poi_roles) AND p.boundary_type = 'park'
  AND p.deleted IS NOT TRUE;

INSERT INTO pois (name, poi_roles, boundary_type, boundary_color, geometry)
SELECT i.name, i.poi_roles, i.boundary_type, i.boundary_color, i.geometry
FROM park_import i
WHERE NOT EXISTS (
  SELECT 1 FROM pois p
  WHERE p.name = i.name
    AND 'boundary' = ANY(p.poi_roles) AND p.boundary_type = 'park'
    AND p.deleted IS NOT TRUE
);

UPDATE pois
SET geometry = ST_AsGeoJSON(ST_UnaryUnion(ST_GeomFromGeoJSON(geometry::text)))::jsonb,
    boundary_geom = ST_Multi(
      ST_CollectionExtract(ST_UnaryUnion(ST_GeomFromGeoJSON(geometry::text)), 3)
    )::geometry(MultiPolygon, 4326)
WHERE boundary_type = 'park'
  AND geometry IS NOT NULL
  AND name IN ('Acacia Reservation', 'Bedford Reservation', 'Big Creek Reservation', 'Bradley Woods Reservation', 'Brecksville Reservation', 'Brookside Reservation', 'Cleveland Lakefront Reservation', 'Euclid Creek Reservation', 'Garfield Park Reservation', 'Hinckley Reservation', 'Huntington Reservation', 'Mill Stream Run Reservation', 'North Chagrin Reservation', 'Ohio & Erie Canal Reservation', 'Rocky River Reservation', 'South Chagrin Reservation', 'Washington Reservation', 'West Creek Reservation');

COMMIT;

-- Verification: exactly one park boundary per reservation and no point twin.
SELECT name, count(*) FILTER (WHERE boundary_type='park') AS park_boundaries,
       count(*) FILTER (WHERE 'point'=ANY(poi_roles)) AS point_markers
FROM pois WHERE name IN ('Acacia Reservation', 'Bedford Reservation', 'Big Creek Reservation', 'Bradley Woods Reservation', 'Brecksville Reservation', 'Brookside Reservation', 'Cleveland Lakefront Reservation', 'Euclid Creek Reservation', 'Garfield Park Reservation', 'Hinckley Reservation', 'Huntington Reservation', 'Mill Stream Run Reservation', 'North Chagrin Reservation', 'Ohio & Erie Canal Reservation', 'Rocky River Reservation', 'South Chagrin Reservation', 'Washington Reservation', 'West Creek Reservation') AND deleted IS NOT TRUE
GROUP BY name ORDER BY name;
